/* Google Maps JavaScript API. Editorial listings supplied by the owner; no partner affiliation implied. */
(()=>{
const regions={all:{name:'All regions',center:[101,4.2],zoom:7},kl:{name:'KL / Selangor',center:[101.65,3.12],zoom:10.4},johor:{name:'Johor',center:[103.75,1.50],zoom:11.1},penang:{name:'Penang',center:[100.31,5.40],zoom:11.1}};
const spots=window.TTSPOT_LISTINGS;
let map,region='all',category='meets',markers=[],loaded=false,timeout,loading=false,authFailed=false,popup,query='',selected=null;
const world=document.createElement('div');world.className='tt-map-world';world.innerHTML='<div class="tt-map-canvas" aria-label="Interactive TTSpot map"></div><div class="tt-map-badge">TTSPOT · DISCOVER</div><button class="tt-map-expand" type="button">Explore map ↗</button><div class="tt-map-status" role="status">Loading map…</div>';
const dashboard=document.querySelector('#dashboard-map-slot'),full=document.querySelector('#full-map-slot'),status=world.querySelector('.tt-map-status');dashboard.append(world);
const results=document.createElement('div');results.className='tt-results';results.setAttribute('aria-label','Matching listings');world.append(results);
const detail=document.createElement('section');detail.className='tt-event-detail';detail.hidden=true;detail.setAttribute('aria-label','Listing details');world.append(detail);
function filtered(){return spots.filter(p=>(region==='all'||p.region===region)&&p.category===category&&[p.title,p.venue,p.address,p.date].join(' ').toLowerCase().includes(query))}
function phase(p){return p.suggested?'Suggested meet spot':p.end&&Date.now()>Date.parse(p.end)?'Past event':p.category==='vendors'?'Vendor':'Event'}
function closeDetail(){detail.hidden=true;selected=null;results.hidden=false}
function show(p){selected=p.id;detail.replaceChildren();detail.hidden=false;results.hidden=true;const close=document.createElement('button');close.className='tt-detail-close';close.textContent='Close';close.onclick=closeDetail;const image=document.createElement('img');image.src=p.image;image.alt=p.title;image.className='tt-detail-image';const body=document.createElement('div');body.className='tt-detail-body';const badge=document.createElement('small');badge.textContent=phase(p);const title=document.createElement('h3');title.textContent=p.title;const when=document.createElement('p');when.textContent=p.date+' · '+p.time;const venue=document.createElement('strong');venue.textContent=p.venue;const address=document.createElement('p');address.textContent=p.address;const actions=document.createElement('div');actions.className='tt-detail-actions';const directions=document.createElement('a');directions.textContent='Directions';directions.href='https://www.google.com/maps/dir/?api=1&destination='+encodeURIComponent(p.venue+' '+p.address);directions.target='_blank';directions.rel='noopener';const source=document.createElement('a');source.textContent=p.suggested?'About this venue':'Listing source';source.href=p.source;source.target='_blank';source.rel='noopener';actions.append(directions,source);const note=document.createElement('small');note.textContent=p.note;body.append(badge,title,when,venue,address,actions,note);detail.append(close,image,body);if(map){map.panTo({lat:p.lat,lng:p.lng});map.setZoom(13)} }
document.querySelector('#map-search').addEventListener('input',e=>{query=e.target.value.trim().toLowerCase();paint();fly()});
document.querySelector('#map-clear').onclick=()=>{query='';region='all';document.querySelector('#map-search').value='';document.querySelector('#map-region').value='all';paint();fly()};


function notice(text,retry=false){status.hidden=false;status.textContent=text;if(retry){const b=document.createElement('button');b.textContent='Reload map';b.onclick=()=>location.reload();status.append(b)}}
window.gm_authFailure=()=>{authFailed=true;clearTimeout(timeout);notice('Google Maps authorization failed. Check the website restriction, Maps JavaScript API and billing settings.');};
function fly(){if(!map)return;const items=filtered();if(items.length){const bounds=new google.maps.LatLngBounds();items.forEach(p=>bounds.extend({lng:p.lng,lat:p.lat}));const box=world.getBoundingClientRect();map.fitBounds(bounds,{top:Math.min(65,box.height*.2),bottom:Math.min(120,box.height*.25),left:Math.min(65,box.width*.15),right:Math.min(65,box.width*.15)});if(items.length===1)map.setZoom(12);return}const r=regions[region],center={lng:r.center[0],lat:r.center[1]};map.setZoom(r.zoom);matchMedia('(prefers-reduced-motion: reduce)').matches?map.setCenter(center):map.panTo(center);}
function paint(){markers.forEach(m=>m.map=null);markers=[];closeDetail();const items=filtered();document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.filter===category)));document.querySelectorAll('[data-map-shortcut]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.mapShortcut===category)));world.querySelector('.tt-map-badge').textContent=({meets:'TT',checkpoints:'AUTOSHOWS',vendors:'VENDORS'}[category])+' · '+items.length+' SPOTS';results.replaceChildren();if(!items.length){const empty=document.createElement('p');empty.className='tt-empty';empty.textContent='No listings here yet. Try All regions or another category.';results.append(empty)}
for(const p of items){const card=document.createElement('button');card.className='tt-result';card.type='button';const photo=document.createElement('img');photo.src=p.thumbnail||p.image;photo.alt='';const text=document.createElement('span');const name=document.createElement('strong');name.textContent=p.title;const meta=document.createElement('small');meta.textContent=p.date+' · '+p.venue;const badge=document.createElement('small');badge.className='tt-result-phase';badge.textContent=phase(p);text.append(name,meta,badge);card.append(photo,text);card.onclick=()=>show(p);results.append(card);if(!map)continue;const el=document.createElement('div');el.className='tt-photo-pin '+(p.suggested?'is-meet-flag':p.category==='vendors'?'is-vendor':'');const image=document.createElement('img');image.src=p.thumbnail||p.image;image.alt=p.title;const label=document.createElement('span');label.textContent=p.short;el.append(image,label);const marker=new google.maps.marker.AdvancedMarkerElement({map,position:{lng:p.lng,lat:p.lat},content:el,title:p.title+' — '+phase(p)});marker.addListener('click',()=>{openPage('navigation');show(p)});markers.push(marker)}}
function resizeMap(){if(map){const center=map.getCenter();google.maps.event.trigger(map,'resize');if(center)map.setCenter(center)}}
function init(){if(map||loading||authFailed)return;loading=true;status.textContent='Loading Google Maps…';status.hidden=false;window.ttspotGoogleReady=()=>{if(authFailed)return;try{const r=regions[region];map=new google.maps.Map(world.querySelector('.tt-map-canvas'),{center:{lng:r.center[0],lat:r.center[1]},zoom:r.zoom,mapId:'DEMO_MAP_ID',colorScheme:google.maps.ColorScheme.DARK,disableDefaultUI:true,zoomControl:false,gestureHandling:'greedy',scrollwheel:true,clickableIcons:false,keyboardShortcuts:true});popup=new google.maps.InfoWindow({maxWidth:240});google.maps.event.addListenerOnce(map,'tilesloaded',()=>{if(authFailed)return;loaded=true;clearTimeout(timeout);status.hidden=true});paint();fly();new ResizeObserver(resizeMap).observe(world);loading=false}catch(e){loading=false;notice('Google Maps could not start. Please reload.',true)}};
const script=document.createElement('script');const params=new URLSearchParams({key:window.TTSPOT_GOOGLE_MAPS_KEY,v:'weekly',loading:'async',libraries:'marker',callback:'ttspotGoogleReady',language:'en',region:'MY'});script.src='https://maps.googleapis.com/maps/api/js?'+params;script.async=true;script.onerror=()=>{loading=false;clearTimeout(timeout);notice('Google Maps could not connect. Please reload.',true)};document.head.append(script);timeout=setTimeout(()=>{if(!loaded&&!authFailed)notice('Google Maps is taking longer to load.',true)},20000);}
function choose(value,expand=true){if(!['meets','checkpoints','vendors'].includes(value))return;category=value;query='';document.querySelector('#map-search').value='';if(expand)openPage('navigation');init();paint();fly()}
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeDetail()});
const originalOpen=openPage;openPage=function(name){originalOpen(name);if(name==='navigation'||name==='dashboard'){(name==='navigation'?full:dashboard).append(world);init();requestAnimationFrame(resizeMap)}};
world.querySelector('.tt-map-expand').onclick=()=>openPage('navigation');document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>choose(b.dataset.filter,false));document.querySelectorAll('[data-map-shortcut]').forEach(b=>b.onclick=()=>choose(b.dataset.mapShortcut,false));document.querySelector('#map-region').onchange=e=>{if(!regions[e.target.value])return;region=e.target.value;paint();fly()};
window.addEventListener('message',e=>{if(e.origin===location.origin&&e.source===parent&&e.data?.type==='ttspot-map')choose(e.data.category)});
const observer=new IntersectionObserver(entries=>{if(entries.some(e=>e.isIntersecting)){init();observer.disconnect()}});observer.observe(dashboard);
})();
